<script setup>
import { confirmAction } from '@/lib/confirm-action.js';
const confirm=window.confirm.bind(window);
import{ref,onMounted}from'vue';import{api}from'@/services/api.js';import{useLearning}from'@/store.js';import{Bookmark,Share2,MessageSquare,RefreshCw}from'@/components/app/icons.js';import{navigate}from'@/lib/navigation.js';
const store=useLearning(),items=ref([]),cases=ref([]),lessons=ref([]),active=ref(null),error=ref(''),busy=ref(false),shareOpen=ref(false),kind=ref('case'),source=ref(''),version=ref(''),savedVersions=ref([]),draftId=ref(''),target=ref(''),text=ref(''),eventKind=ref('discussion'),taskId=ref('');
const call=(path,method='GET',body)=>api.request('/community'+path,{method,...(body?{body:JSON.stringify(body)}:{})});
async function load(){try{items.value=await call('');if(active.value)active.value=items.value.find(s=>s.id===active.value.id)||null}catch(e){error.value=e.message}}
onMounted(async()=>{try{await load();const c=await api.request('/curriculum/courses');lessons.value=c.flatMap(c=>c.units.flatMap(u=>u.lessons));const r=await api.request('/ai/search?q=');cases.value=r.items||[];source.value=cases.value[0]?.id||'';target.value=lessons.value[0]?.id||''}catch(e){error.value=e.message}});
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function planVersions(){await run(async()=>{const d=await api.request('/platform?lessonId='+target.value);draftId.value=d.lessonDraft.id;savedVersions.value=await api.request('/preparation/'+target.value+'/versions');version.value=savedVersions.value[0]?.id||''})}
async function share(){if(!await confirmAction('确认将这个版本分享给其他教师？不会自动公开其他私有草稿。'))return;await run(async()=>{const c=cases.value.find(c=>c.id===source.value);active.value=await call('','POST',{kind:kind.value,sourceId:kind.value==='case'?source.value:draftId.value,versionId:kind.value==='case'?c?.versionId:version.value,confirmed:true});shareOpen.value=false;await load()})}
async function adapt(){await run(async()=>{const r=await call('/'+active.value.id+'/adapt','POST',{lessonId:target.value});navigate('prepare?lesson='+r.lessonId)})}
</script>
<template><PageHeading title="教研交流"><AppButton @click="shareOpen=true"><Share2 :size="16"/>分享内容</AppButton><AppButton variant="ghost" aria-label="刷新分享" @click="load"><RefreshCw :size="16"/></AppButton></PageHeading><AppAlert type="error" v-if="error" role="alert" class="form-error">{{error}}</AppAlert><div class="community-layout"><aside><AppButton variant="ghost" data-layout="row" type="button" v-for="s in items" :key="s.id" class="exam-paper-link" @click="active=s"><Status>{{s.kind==='case'?'案例':'教案'}}{{s.active?'':' 　 已撤回'}}</Status><strong>{{s.snapshot.title}}</strong><span>{{s.author}} 　 {{new Date(s.createdAt).toLocaleDateString('zh-CN')}}</span></AppButton><AppEmpty v-if="!items.length" class="empty-state">暂无公开分享</AppEmpty></aside><Surface v-if="active"><div class="exam-toolbar"><AppButton variant="outline" :disabled="busy||!active.active" @click="run(async()=>{active=await call('/'+active.id+'/bookmark','PUT',{selected:!active.bookmarked});await load()})"><Bookmark :size="16"/>{{active.bookmarked?'取消收藏':'收藏'}}</AppButton><AppButton v-if="active.ownerId===store.user?.id&&active.active" variant="ghost" :disabled="busy" @click="run(async()=>{if(await confirmAction('撤回后其他教师不能继续访问此分享，既有改编来源仍保留。')){await call('/'+active.id+'/withdraw','POST',{});await load()}})">撤回分享</AppButton></div><h2>{{active.snapshot.title}}</h2><div class="ops-community-author">{{active.author}} 　 {{new Date(active.createdAt).toLocaleDateString('zh-CN')}}</div><AppDisclosure class="ops-disclosure"><template #title>作者与来源</template><p>原作者 {{active.snapshot.author||(active.kind==='case'?'未署名':active.author)}} 　 {{active.snapshot.source||'已保存教案版本'}}</p><RouteButton v-if="active.kind==='case'" :route="'case-detail?caseId='+active.sourceId+'&versionId='+active.snapshot.versionId" secondary>查看来源案例</RouteButton></AppDisclosure><div class="community-prose">{{active.snapshot.content||active.snapshot.goal}}</div><section v-for="b in active.snapshot.blocks||[]" :key="b.id"><h3>{{b.title}}</h3><p class="community-prose">{{b.content}}</p></section><AppDisclosure v-if="active.active" class="ops-disclosure"><template #title>改编为我的教案</template><div class="teaching-form-row"><label>改编到课时<NativeSelect v-model="target"><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></NativeSelect></label><AppButton variant="outline" :disabled="busy" @click="adapt">创建改编草稿</AppButton></div></AppDisclosure><Surface data-ui="card" class="community-discussion"><h3>讨论与使用反馈</h3><Surface data-ui="card" role="article" v-for="e in active.events" :key="e.id"><div><strong>{{e.author}}</strong><time>{{new Date(e.at).toLocaleString('zh-CN')}}</time></div><p v-if="e.withdrawn">作者已撤回，历史操作保留</p><template v-else><p>{{e.kind==='adaptation'?'已创建改编教案':e.data.text}}</p><small v-if="e.kind==='feedback'">{{e.data.basis}}</small><AppButton v-if="e.ownerId===store.user?.id&&e.kind!=='adaptation'" variant="ghost" :disabled="busy" @click="run(async()=>{active=await call('/'+active.id+'/events/'+e.id+'/withdraw','POST',{})})">撤回内容</AppButton></template></Surface><template v-if="active.active"><NativeSelect v-model="eventKind" aria-label="反馈类型"><option value="discussion">讨论</option><option value="feedback">使用反馈（个人自述）</option></NativeSelect><NativeSelect v-if="eventKind==='feedback'" v-model="taskId" aria-label="实际使用任务"><option value="">未关联任务 　 个人自述</option><option v-for="t in store.data.tasks" :key="t.id" :value="t.id">{{t.title}}</option></NativeSelect><label class="teaching-label">内容<Textarea v-model="text" aria-label="讨论或使用反馈"/></label><AppButton :disabled="busy||!text.trim()" @click="run(async()=>{active=await call('/'+active.id+'/events','POST',{kind:eventKind,text,taskId:eventKind==='feedback'?(taskId||null):null});text=''})"><MessageSquare :size="16"/>发布</AppButton></template></Surface></Surface><Surface v-else><AppEmpty class="empty-state">选择左侧分享</AppEmpty></Surface></div><AppDialog v-model:open="shareOpen" title="分享指定版本"><div class="teaching-label"><label>内容类型<NativeSelect v-model="kind"><option value="case">已发布案例</option><option value="plan">本人已保存教案</option></NativeSelect></label><label v-if="kind==='case'">案例<NativeSelect v-model="source"><option v-for="c in cases" :key="c.id" :value="c.id">{{c.title}} 　 v{{c.version}}</option></NativeSelect></label><template v-else><label>课时<NativeSelect v-model="target"><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></NativeSelect></label><AppButton variant="outline" @click="planVersions">读取本人保存版本</AppButton><label>版本<NativeSelect v-model="version"><option v-for="v in savedVersions" :key="v.id" :value="v.id">v{{v.number}} 　 {{v.reason}}</option></NativeSelect></label></template><AppButton :disabled="busy||(kind==='plan'&&!version)" @click="share">确认分享此版本</AppButton></div></AppDialog></template>
